self.onmessage=async e=>{const start=performance.now();try{const {derived,candidate}=e.data;let trace=e.data.trace;const reused=!!e.data.knownResult,crossingStarted=performance.now();if(!reused&&derived.versions?.derivation==='stitch-derived-v1'&&!trace)trace=await reconstructStitchTrace(candidate.boundary,candidate.source,candidate.board,candidate.context,candidate.generation,derived);const result=e.data.knownResult||findCrossings(derived.strands,trace),crossingMs=performance.now()-crossingStarted,markupStarted=performance.now(),markup=continuousWeaveSvg(derived.strands,result,e.data.settings,e.data.appearance,derived.provenanceFingerprint,candidate.boundary),markupMs=performance.now()-markupStarted;self.postMessage({id:e.data.id,result,markup,reused:reused?['crossings']:[],timing:{crossingMs,markupMs},workerMs:performance.now()-start});}catch(error){self.postMessage({id:e.data.id,error:error.message});}};
